def _qform(A, x):
    """Q(x) = x^T A x (exact; A rational, need not be symmetric)."""
    n = len(x)
    return sum(A[i][j] * x[i] * x[j]
               for i in range(n) for j in range(n))


def _d2(A, base, v):
    """the second central difference Q(b+v) + Q(b-v) - 2 Q(b); for a
    quadratic form this equals 2 v^T A_sym v EXACTLY at every base
    and step (the r292 diagonal protocol, exact skeleton)."""
    xp = [b + w for b, w in zip(base, v)]
    xm = [b - w for b, w in zip(base, v)]
    return _qform(A, xp) + _qform(A, xm) - 2 * _qform(A, base)


def _pol(A, base, u, v, wrong_prefactor=False):
    """the r292 polarization H(u, v) = [d2(u+v) - d2(u-v)] / 4; the
    mutant flag replaces the correct /4 by /2."""
    up = [a + b for a, b in zip(u, v)]
    um = [a - b for a, b in zip(u, v)]
    den = 2 if wrong_prefactor else 4
    return (_d2(A, base, up) - _d2(A, base, um)) / den


def _pol_expand(A, base, u, v):
    """the r292 expansion-identity crosscheck
    [d2(u+v) - d2(u) - d2(v)] / 2 (exact)."""
    up = [a + b for a, b in zip(u, v)]
    return (_d2(A, base, up) - _d2(A, base, u) - _d2(A, base, v)) / 2


def _pair_true(A, u, v):
    """the exact symmetrized pairing u^T A v + v^T A u."""
    n = len(u)
    return sum(A[i][j] * (u[i] * v[j] + v[i] * u[j])
               for i in range(n) for j in range(n))


def _budget(c, mask, dose, drop=None):
    """the r291 side-selected first-order budget
    b(A) = -sum_{j in A} c_j x dose (exact); the mutant flag drops
    one index from A (the dropped-atom mutant)."""
    return -sum(c[j] for j in mask if j != drop) * dose


def _alpha_doubling(h, t0, d):
    """the r293 alpha estimator as an exact doubling ratio:
    |h(t0 + 2d)| / |h(t0 + d)| == 2^alpha for h = c (t - t0)^alpha
    (exact Fractions; alpha read off as the exact power of 2)."""
    r = abs(h(t0 + 2 * d)) / abs(h(t0 + d))
    for a in (1, 2, 3):
        if r == 2 ** a:
            return a, r
    return None, r


def _bar_r295(wins, med, minm, n=20):
    """the sealed r295 three-clause HARDENED bar (exact decision
    logic on the aggregates): F10_SP_HARDENED iff wins >= 18/n AND
    median >= +0.02 AND min margin >= -0.02; else F10_SP_MAJORITY
    iff wins >= 14 (incl. the disclosed >= 18-with-failed-margin-
    clause sub-case); else F10_SP_DEAD."""
