def scope_audit(funcname, forbidden):
    src = open(os.path.abspath(__file__), "r", encoding="utf-8").read()
    tree = ast.parse(src)
    hits = []
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef) and node.name == funcname:
            for sub in ast.walk(node):
                nm = None
                if isinstance(sub, ast.Attribute):
                    nm = sub.attr
                elif isinstance(sub, ast.Name):
                    nm = sub.id
                elif isinstance(sub, ast.Constant) \
                        and isinstance(sub.value, str):
                    nm = sub.value
                if nm in forbidden:
                    hits.append("%s@%d" % (nm, sub.lineno))
    return hits


# ============== sealed source-pure constructors (AST-audited)
def partial_sp(fv, sv, bv):
    """sealed PARTIAL SPEARMAN: first-order partial rank
    correlation r(F, s | b) = (r_Fs - r_Fb r_sb) /
    sqrt((1 - r_Fb^2)(1 - r_sb^2)) on Spearman correlations;
    nan (DEGENERATE, disclosed) when a conditioning correlation
    is within 1e-12 of +-1.  Consumes three lists only."""
    r_fs = BH.spearman(fv, sv)
    r_fb = BH.spearman(fv, bv)
    r_sb = BH.spearman(sv, bv)
    den2 = (1.0 - r_fb * r_fb) * (1.0 - r_sb * r_sb)
    if den2 <= DEGEN_EPS * DEGEN_EPS:
        return float("nan")
    return (r_fs - r_fb * r_sb) / math.sqrt(den2)


def spectral_abs(Hm):
    """SPECTRAL ABSOLUTE VALUE |H| = U |Lam| U^T of a symmetric
    matrix (the sealed M3 well-definedness rule; |H| == -H
    exactly iff H is negative semidefinite).  Consumes a matrix
    only."""
    w, U = np.linalg.eigh(np.asarray(Hm, float))
    return (U * np.abs(w)[None, :]) @ U.T


def alpha_pair_slopes(eps_list, lvals):
    """sealed singularity-exponent auditor: adjacent pair slopes
    alpha_i = [L(eps_{i+1}) - L(eps_i)] / log(eps_{i+1}/eps_i)
    of log|h| against log|f - f*|; None (NOT VERIFIABLE) with
    fewer than three points.  Consumes two lists only."""
    if len(eps_list) < 3 or len(lvals) < 3:
        return None
    out = []
    for i in range(len(eps_list) - 1):
        out.append((float(lvals[i + 1]) - float(lvals[i]))
                   / math.log(float(eps_list[i + 1])
                              / float(eps_list[i])))
    return out


def dist_m3(x, Aabs):
    """M3 distance on the projection coordinates: sqrt(x^T |H| x)
    (the curvature wall unit; span restriction disclosed).
    Consumes a vector + the |H| matrix only."""
    x = np.asarray(x, float)
    v = float(x @ np.asarray(Aabs, float) @ x)
    return math.sqrt(max(v, 0.0))


def func_f13(x, Hm, Aabs):
    """F13 WHITENED CURVATURE: x^T H x / (2 x^T |H| x) -- the
    curvature energy in the M3 whitening basis per unit M3
    energy, bounded in [-1/2, +1/2]; == -1/2 exactly on the
    negative eigenspace (near-degeneracy vs the M3 baseline
    DISCLOSED); 0.0 sealed at zero deviation."""
    x = np.asarray(x, float)
    r3sq = float(x @ np.asarray(Aabs, float) @ x)
    if float(np.max(np.abs(x))) == 0.0 or r3sq <= 0.0:
        return 0.0
    return 0.5 * float(x @ np.asarray(Hm, float) @ x) / r3sq


def func_f14(x, g, Hm, Aabs):
    """F14 BUDGET + CURVATURE PER WALL UNIT: g^T x / |x|_M3 +
    x^T H x / (2 |x|_M3^2) -- the r291 first-order term and the
    two-form in the common M3 unit; 0.0 sealed at zero
    deviation."""
    x = np.asarray(x, float)
    r3sq = float(x @ np.asarray(Aabs, float) @ x)
    if float(np.max(np.abs(x))) == 0.0 or r3sq <= 0.0:
        return 0.0
    r3 = math.sqrt(r3sq)
    return float(np.asarray(g, float) @ x) / r3 \
        + 0.5 * float(x @ np.asarray(Hm, float) @ x) / r3sq


def band_split_ranks(vals, n_bands):
    """rank-quartile band index of a value list (stable argsort,
    contiguous equal-size bands).  Consumes a list only."""
    vals = np.asarray(vals, float)
    order = np.argsort(vals, kind="stable")
    idx = np.empty(len(vals), int)
    for b, chunk in enumerate(np.array_split(order, n_bands)):
        idx[chunk] = b
    return idx


